import manifest from '../data/image-manifest.json'

const BASE = `${import.meta.env.BASE_URL}images/`

const srcset = (name, ext) =>
  manifest[name].widths.map((w) => `${BASE}${name}-${w}.${ext} ${w}w`).join(', ')

/**
 * Responsive <picture> with AVIF + WebP sources generated by
 * `npm run images`. Intrinsic width/height come from the manifest so the
 * browser reserves space and avoids layout shift.
 *
 * `art` optionally swaps to a different crop below a breakpoint
 * (e.g. a portrait hero crop on phones).
 */
export default function Picture({
  name,
  alt,
  sizes = '100vw',
  priority = false,
  art,
  className,
  ...rest
}) {
  const meta = manifest[name]
  if (!meta) {
    if (import.meta.env.DEV) console.warn(`[Picture] Unknown image "${name}". Run npm run images.`)
    return null
  }
  const largest = meta.widths[meta.widths.length - 1]

  return (
    <picture className={className}>
      {art && (
        <>
          <source media={art.media} type="image/avif" srcSet={srcset(art.name, 'avif')} sizes={art.sizes || sizes} />
          <source media={art.media} type="image/webp" srcSet={srcset(art.name, 'webp')} sizes={art.sizes || sizes} />
        </>
      )}
      <source type="image/avif" srcSet={srcset(name, 'avif')} sizes={sizes} />
      <source type="image/webp" srcSet={srcset(name, 'webp')} sizes={sizes} />
      <img
        src={`${BASE}${name}-${largest}.webp`}
        alt={alt}
        width={meta.width}
        height={meta.height}
        loading={priority ? 'eager' : 'lazy'}
        decoding={priority ? 'sync' : 'async'}
        fetchPriority={priority ? 'high' : undefined}
        {...rest}
      />
    </picture>
  )
}
